"""Write an evidence-bound interim report for the first closed large campaign."""
import json
from pathlib import Path
from ftqec.results.artifacts import source_identity,save
s=source_identity();root=Path('results/large_scale/reports')/s;root.mkdir(parents=True,exist_ok=True)
index_path=Path('results/exports/large_scale')/s/'first_closed_campaign/index.json';index=json.loads(index_path.read_text());protocol=json.loads(index_path.with_name('protocol.json').read_text());audit_path=Path(protocol['audit']);audit=json.loads(audit_path.read_text());run=audit['runs'][0];receipt=run['outer_receipt'];costs=run['costs'];cpu=sum(v['cpu'] for v in costs.values());points=sorted(index['records'],key=lambda r:(r['resources']['Q'],r['resources']['D']))
lines=['# FTQEC large-population interim evidence','', '**Status: one large surface-code campaign independently audited and its adopted frontier exported; the full research cycle remains in progress.**','',f'Scientific source: `{s}`. This report concerns only `{run["job"]["name"]}`. It is not the final cross-family or matched-compute assessment.','', '## Completed campaign','', '| Quantity | Observed |','|---|---:|']
for label,value in [('Generated attempts',run['generated_attempts']),('Noiseless-valid attempts',run['counts']['noiseless_valid_attempts']),('Distinct serialized circuit payloads',run['counts']['distinct_constructed_payloads']),('Distinct indexed physical identities',run['counts']['distinct_compiled']),('Distinct timed structures',run['meaningful_structures']),('Ancilla-relabel-invariant structural classes',run['ancilla_relabel_invariant_classes']),('Distinct screened candidates',run['counts']['screened']),('Distinct simulated candidates',run['counts']['simulated']),('Completed simulation batches',costs['simulation']['executions']),('Simulation shots',costs['simulation']['shots']),('Distinct certification attempts',run['counts']['certification_attempted']),('Positive certificates with recorded independent checks',run['counts']['certified']),('Verified invalid candidates',run['counts']['invalid']),('Uncompleted attempted proofs',run['counts'].get('unknown',0)),('Replayed harmful and upper witnesses',len(run['witness_replays']))]:lines.append(f'| {label} | {value:,} |')
lines+=['','The stronger structural invariant removes arbitrary ancilla naming as well as cosmetic operation ordering. Different invariant values distinguish timed structures with fixed data-wire labels; this does not quotient every stabilizer-code automorphism or prove that equal signatures are isomorphic. Payload, physical-identity, and structural counts are intentionally separate.','', 'All generated attempts in this run passed noiseless validation. Candidates that did not reach certification remain uncertified; zero unfinished attempted proofs does not mean that the entire population was certified. The full archive retains deferred candidates and invalid outcomes.','', '## Independently replayed adopted resource frontier','', '| Q | D | QD | Two-qubit gates | Exact circuit | Export |','|---:|---:|---:|---:|---|---|']
for row in points:
 r=row['resources'];lines.append(f'| {r["Q"]} | {r["D"]} | {r["QD"]} | {r["two_q_gates"]} | `{row["circuit"]}` | [{row["id"][:12]}]({Path(row["bundle"]).resolve().as_posix()}) |')
lines+=['', 'Every listed export passed fresh independent positive-certificate replay, exact schedule reconstruction, resource recomputation, and identity binding. Equal-resource circuit alternatives remain in the population archive; only deterministic representatives are listed here.','', 'These are extraction-distance-3 results under operation-local physical faults with ideal code-space boundaries. They are not arbitrary-input physical-memory, hardware-routing, decoder-independent reliability, or global-optimality claims.','', '## Measured compute','', '| Stage | Whole-worker CPU seconds | Summed worker wall seconds (overlapping) | Shots |','|---|---:|---:|---:|']
for tier,v in sorted(costs.items()):lines.append(f'| {tier} | {v["cpu"]:.6f} | {v["summed_wall"]:.6f} | {v["shots"]} |')
lines += ['',f'Outer campaign elapsed wall: {receipt["elapsed_call_wall"]:.6f} seconds. Controller CPU: {receipt["controller_call_cpu"]:.6f} seconds. Whole-worker CPU: {cpu:.6f} seconds. The two CPU categories sum to {cpu+receipt["controller_call_cpu"]:.6f} CPU seconds; nested session clocks are not added again. Summed worker wall is not campaign elapsed time.', '',f'Sampled controller peak: {receipt["peak_sampled_controller_rss"]} bytes. Sampled simultaneous worker-aggregate peak: {receipt["peak_sampled_worker_aggregate_rss"]} bytes. These are separate maxima and are not summed to invent a simultaneous total. Sampling can miss brief peaks.', '',f'The separate full-population audit used {run["audit_cpu"]:.6f} controller CPU seconds and {run["audit_wall"]:.6f} elapsed seconds. Individual export replay costs are retained in the export index. These verification costs are outside the optimization campaign.', '', 'Installation dependency copying and lightweight audits overlapped part of this campaign. Its wall-clock result is an observational local measurement, not an isolated-machine benchmark. The separate serial/parallel experiment was measured on identical fresh tasks; that workload-specific speedup is not a whole-optimizer speedup claim.', '', '## What remains unresolved','', 'The larger-capacity run, independent seeds, other CSS families, isolated evaluation-policy study, final matched-decoder LER study, and final evidence package are still pending. New resource tradeoffs found after additional computation do not by themselves prove that a larger population or an adaptive policy is superior at matched compute. Historical distance-5 and distance-10 results remain separate controls.', '', '## Raw evidence','']
for label,p in [('Full candidate audit',audit_path),('Freshly verified exports',index_path),('Campaign receipt',Path('results/populations')/s/'study'/run['job']['name']/'experiment_receipt.json'),('Frozen campaign protocol',Path('results/large_scale/campaigns')/s/'protocol.json'),('Closed population database',Path('results/populations')/s/'study'/run['job']['name']/'population.sqlite')]:lines.append(f'- [{label}]({p.resolve().as_posix()})')
reference_path=Path('results/large_scale/references')/s/'surface3_noiseless_normalized/summary.json'
reference=json.loads(reference_path.read_text());assert reference['verification']['positive_certificate_verified']
best=min(points,key=lambda r:r['resources']['QD']);same=all(best['resources'][k]==reference['resources'][k] for k in ('Q','D','QD','two_q_gates'));assert same
lines+=['','## Separate reference comparison','',f'The separately compiled, independently certified reference has Q={reference["resources"]["Q"]}, D={reference["resources"]["D"]}, QD={reference["resources"]["QD"]}, and {reference["resources"]["two_q_gates"]} two-qubit gates. Its stabilizer span on the same data-wire labels matches the benchmark input. The autonomous campaign matches this resource tuple and retains lower-qubit alternatives. This is resource competitiveness on this code, not a general optimality statement.','', 'The smaller completed 139-structure campaign already contained the Q=17, D=8 tuple. The larger campaign does not establish a better minimum QD merely by rediscovering it. Additional intermediate resource alternatives must still be assessed at matched compute.', '',f'[Reference certification and verification]({reference_path.resolve().as_posix()}). The reference was generated separately after the first large campaign and was never supplied to the optimizer. Its initial export attempt correctly rejected a certificate binding before explicit zero detector offsets were normalized; that failed engineering attempt and its original driver are retained under `results/large_scale/references/{s}/surface3/`. The corrected, noiselessly validated reference uses a new directory.']
path=root/'FIRST_CLOSED_CAMPAIGN.md';path.write_text('\n'.join(lines)+'\n',encoding='utf-8');save(root/'first_closed_report_identity.json',dict(source=s,report=str(path),audit=str(audit_path),exports=str(index_path)));print(path)